import {getRegion} from './region.js?v=8.9';
import {esc,num} from './marine-charts.js?v=8.9';
import {readConditions} from './marine-data.js?v=8.9';
const api=async(path,options={})=>{const r=await fetch('/api/'+path,{signal:AbortSignal.timeout(20000),...options,headers:{'Content-Type':'application/json',...options.headers}});let data;try{data=await r.json();}catch{throw Error('Personal services are available on the published site.');}if(!r.ok)throw Error(data.error||'Could not complete this request.');return data;};
const b64=s=>Uint8Array.from(atob(s.replaceAll('-','+').replaceAll('_','/')+'='.repeat((4-s.length%4)%4)),c=>c.charCodeAt(0));
export async function initTripAlerts(intelligence){
  const host=document.getElementById('trip-alerts'),comfort=document.getElementById('comfort-feedback');if(!host)return;
  let session;try{session=await api('session');}catch{host.innerHTML='<details class="insight-card"><summary>Saved-trip alerts</summary><p>Personal alerts are available on the published site. Retry after connecting.</p></details>';return;}
  if(!session.signedIn){const link='<a href="/signin-with-chatgpt?return_to=%2F%23forecast" target="_top">Sign in with ChatGPT</a>';host.innerHTML=`<details class="insight-card"><summary>Saved-trip alerts</summary><p>Save a date, area and comfort limits. Receive material changes and a day-before assessment.</p>${link}<p class="small">The map stays public. Saved trips and delivery settings are private to your account.</p></details>`;comfort.innerHTML=`<p class="small">${link} to save your Parker comfort feedback.</p>`;return;}
  const r=getRegion();const date=new Intl.DateTimeFormat('en-CA',{timeZone:r.timezone}).format(new Date(Date.now()+86400000));
  host.innerHTML=`<details class="insight-card"><summary>My trip alerts</summary><form id="save-alert" class="insight-form"><label>Trip date<input name="date" type="date" value="${date}" required></label><label>Area<select name="point">${r.forecast_points.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>From · local hour<input name="start_hour" type="number" min="0" max="22" value="7" required></label><label>Until · local hour<input name="end_hour" type="number" min="1" max="23" value="13" required></label><label>Wind limit · kt<input name="wind_limit" type="number" min="1" max="30" value="8" required></label><label>Gust limit · kt<input name="gust_limit" type="number" min="1" max="40" value="12" required></label><label>Sea limit · ft<input name="sea_limit" type="number" min="0.5" max="10" step="0.5" value="3" required></label><button>Save this fishing window</button></form><p class="small">Uses the selected target species. These alerts assess the saved area's weather window and reviewed rules; they do not plan navigation or predict catches.</p><div class="inavx-actions"><button id="enable-push">Enable notifications on this device</button><button id="disable-push">Stop notifications</button></div><p id="alert-status" role="status"></p><div id="saved-trips"></div><div id="alert-history"></div><details><summary>Privacy & account data</summary><p>Trips, notification endpoints and comfort feedback are stored privately. Delete a trip to stop its monitoring. Comfort feedback is retained for one year; trips and assessments for 90 days.</p><button id="export-private">Export my records</button><button id="delete-private">Delete all my records</button><a href="/signout-with-chatgpt?return_to=%2F" target="_top">Sign out</a></details></details>`;
  const status=message=>{document.getElementById('alert-status').textContent=message;};
  async function refresh(){try{const data=await api('trips');document.getElementById('saved-trips').innerHTML=data.trips.length?data.trips.map(t=>`<p><strong>${esc(t.date)} · ${esc(t.point)}</strong> · ${esc(t.species)} · ${t.start_hour}:00–${t.end_hour}:00 <button data-delete-trip="${esc(t.id)}">Delete</button></p>`).join(''):'<p>No saved trips.</p>';document.getElementById('alert-history').innerHTML=data.events.length?`<details><summary>Recent assessments (${data.events.length})</summary>${data.events.map(e=>`<article><strong>${esc(e.kind)} · ${esc(e.status)}</strong><p style="white-space:pre-line">${esc(e.message)}</p>${!['read','delivered'].includes(e.status)?`<button data-ack-event="${e.id}">Mark read</button>`:''}</article>`).join('')}</details>`:'';}catch(e){status(e.message);}}
  document.getElementById('save-alert').addEventListener('submit',async e=>{e.preventDefault();const form=Object.fromEntries(new FormData(e.target));for(const k of ['start_hour','end_hour','wind_limit','gust_limit','sea_limit'])form[k]=Number(form[k]);try{await api('trips',{method:'POST',body:JSON.stringify({...form,region:r.id,species:document.getElementById('species-select').value})});status('Trip saved. Scheduled checks run about every 30 minutes; notifications require device permission.');refresh();}catch(error){status(error.message);}});
  host.addEventListener('click',async e=>{const remove=e.target.closest('[data-delete-trip]'),ack=e.target.closest('[data-ack-event]');try{if(remove){await api('trips',{method:'DELETE',body:JSON.stringify({id:remove.dataset.deleteTrip})});refresh();}if(ack){await api('events/ack',{method:'POST',body:JSON.stringify({id:ack.dataset.ackEvent})});refresh();}}catch(error){status(error.message);}});
  document.getElementById('enable-push').addEventListener('click',async()=>{
    try{
      if(!('serviceWorker' in navigator)||!('PushManager' in window)||!session.publicKey)throw Error('Notifications are not available here. On iPad/iPhone, add SkipperCast to the Home Screen and open it there.');
      const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notifications were not enabled. You can still read assessments here.');
      const registration=await navigator.serviceWorker.register('/sw.js');await navigator.serviceWorker.ready;
      const subscription=await registration.pushManager.getSubscription()||await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:b64(session.publicKey)});
      await api('subscription',{method:'POST',body:JSON.stringify(subscription.toJSON())});status('Notifications enabled on this device. Saved trips are checked automatically.');
    }catch(error){status(error.message);}
  });
  document.getElementById('disable-push').addEventListener('click',async()=>{try{await api('subscription',{method:'DELETE'});const registration=await navigator.serviceWorker?.getRegistration('/sw.js');await(await registration?.pushManager.getSubscription())?.unsubscribe();status('Account notifications stopped. Saved assessments remain available here.');}catch(error){status(error.message);}});
  document.getElementById('export-private').addEventListener('click',async()=>{try{const d=await api('privacy'),url=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='SkipperCast-private-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){status(error.message);}});
  document.getElementById('delete-private').addEventListener('click',async()=>{if(!confirm('Delete all saved trips, notification subscriptions, assessments and comfort feedback?'))return;try{await api('privacy',{method:'DELETE'});status('Your saved records have been deleted.');refresh();}catch(error){status(error.message);}});
  comfort.innerHTML=`<details><summary>How did the Parker feel today?</summary><form id="comfort-form" class="insight-form"><label>Part of trip<select name="phase"><option value="outbound">Outbound</option><option value="fishing">Fishing</option><option value="return">Return</option></select></label><label>Comfort · 1 rough to 10 excellent<input name="rating" type="number" min="1" max="10" value="7" required></label><button>Save private feedback</button></form><p id="comfort-status" role="status"></p><div id="comfort-history"></div></details>`;
  async function feedbackHistory(){try{const d=await api('comfort');document.getElementById('comfort-history').innerHTML=`<p class="small">${d.feedback.length} private reports. These describe your experience; they do not automatically alter public ratings or assert a boat-motion model.</p>${d.feedback.slice(0,5).map(f=>`<p>${esc(new Date(f.observed_at).toLocaleDateString())} · ${f.rating}/10 · ${esc(JSON.parse(f.context).phase)}</p>`).join('')}`;}catch{}}
  document.getElementById('comfort-form').addEventListener('submit',async e=>{e.preventDefault();const state=intelligence.getState(),c=state?readConditions(state.bundle,state.point,state.time,state.family):{};const form=Object.fromEntries(new FormData(e.target));const past=state&&Math.abs(state.time-Date.now()/1000)>3600;try{await api('comfort',{method:'POST',body:JSON.stringify({region:r.id,rating:Number(form.rating),phase:form.phase,wind:past?null:c.wind,sea:past?null:c.sea?.height,period:past?null:c.sea?.period,heading:document.getElementById("comfort-heading").value===""?null:Number(document.getElementById("comfort-heading").value),point:state?r.forecast_points[state.point].id:null})});document.getElementById('comfort-status').textContent='Saved privately. Forecast context is attached only when the selected hour is near now.';feedbackHistory();}catch(error){document.getElementById('comfort-status').textContent=error.message;}});
  refresh();feedbackHistory();
}
